# GraphrtError
# We want to define each variant as a nested class that's also a subclass,
# which is tricky in Python.  To accomplish this we're going to create each
# class separately, then manually add the child classes to the base class's
# __dict__.  All of this happens in dummy class to avoid polluting the module
# namespace.
class GraphrtError(Exception):
    """
    Errors surfaced to foreign code as exceptions.
"""
    pass

_UniffiTempGraphrtError = GraphrtError

class GraphrtError:  # type: ignore
    """
    Errors surfaced to foreign code as exceptions.
"""
    
    class InvalidConfig(_UniffiTempGraphrtError):
        """
        The runtime configuration JSON is invalid.
"""
        
        def __init__(self, message):
            super().__init__(", ".join([
                "message={!r}".format(message),
            ]))
            self.message = message

        def __repr__(self):
            return "GraphrtError.InvalidConfig({})".format(str(self))
    _UniffiTempGraphrtError.InvalidConfig = InvalidConfig # type: ignore
    class InvalidWorkflow(_UniffiTempGraphrtError):
        """
        The workflow document could not be parsed or compiled.
"""
        
        def __init__(self, message):
            super().__init__(", ".join([
                "message={!r}".format(message),
            ]))
            self.message = message

        def __repr__(self):
            return "GraphrtError.InvalidWorkflow({})".format(str(self))
    _UniffiTempGraphrtError.InvalidWorkflow = InvalidWorkflow # type: ignore
    class InvalidInput(_UniffiTempGraphrtError):
        """
        Run inputs, snapshot or selector JSON is invalid.
"""
        
        def __init__(self, message):
            super().__init__(", ".join([
                "message={!r}".format(message),
            ]))
            self.message = message

        def __repr__(self):
            return "GraphrtError.InvalidInput({})".format(str(self))
    _UniffiTempGraphrtError.InvalidInput = InvalidInput # type: ignore
    class Plugin(_UniffiTempGraphrtError):
        """
        A WebAssembly plugin could not be loaded.
"""
        
        def __init__(self, message):
            super().__init__(", ".join([
                "message={!r}".format(message),
            ]))
            self.message = message

        def __repr__(self):
            return "GraphrtError.Plugin({})".format(str(self))
    _UniffiTempGraphrtError.Plugin = Plugin # type: ignore
    class Runtime(_UniffiTempGraphrtError):
        """
        Internal failure (runtime could not start, lock poisoned...).
"""
        
        def __init__(self, message):
            super().__init__(", ".join([
                "message={!r}".format(message),
            ]))
            self.message = message

        def __repr__(self):
            return "GraphrtError.Runtime({})".format(str(self))
    _UniffiTempGraphrtError.Runtime = Runtime # type: ignore
    class Unsupported(_UniffiTempGraphrtError):
        """
        The capability is not compiled into this build, or not configured.
"""
        
        def __init__(self, message):
            super().__init__(", ".join([
                "message={!r}".format(message),
            ]))
            self.message = message

        def __repr__(self):
            return "GraphrtError.Unsupported({})".format(str(self))
    _UniffiTempGraphrtError.Unsupported = Unsupported # type: ignore

GraphrtError = _UniffiTempGraphrtError # type: ignore
del _UniffiTempGraphrtError


class _UniffiFfiConverterTypeGraphrtError(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return GraphrtError.InvalidConfig(
                _UniffiFfiConverterString.read(buf),
            )
        if variant == 2:
            return GraphrtError.InvalidWorkflow(
                _UniffiFfiConverterString.read(buf),
            )
        if variant == 3:
            return GraphrtError.InvalidInput(
                _UniffiFfiConverterString.read(buf),
            )
        if variant == 4:
            return GraphrtError.Plugin(
                _UniffiFfiConverterString.read(buf),
            )
        if variant == 5:
            return GraphrtError.Runtime(
                _UniffiFfiConverterString.read(buf),
            )
        if variant == 6:
            return GraphrtError.Unsupported(
                _UniffiFfiConverterString.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if isinstance(value, GraphrtError.InvalidConfig):
            _UniffiFfiConverterString.check_lower(value.message)
            return
        if isinstance(value, GraphrtError.InvalidWorkflow):
            _UniffiFfiConverterString.check_lower(value.message)
            return
        if isinstance(value, GraphrtError.InvalidInput):
            _UniffiFfiConverterString.check_lower(value.message)
            return
        if isinstance(value, GraphrtError.Plugin):
            _UniffiFfiConverterString.check_lower(value.message)
            return
        if isinstance(value, GraphrtError.Runtime):
            _UniffiFfiConverterString.check_lower(value.message)
            return
        if isinstance(value, GraphrtError.Unsupported):
            _UniffiFfiConverterString.check_lower(value.message)
            return

    @staticmethod
    def write(value, buf):
        if isinstance(value, GraphrtError.InvalidConfig):
            buf.write_i32(1)
            _UniffiFfiConverterString.write(value.message, buf)
        if isinstance(value, GraphrtError.InvalidWorkflow):
            buf.write_i32(2)
            _UniffiFfiConverterString.write(value.message, buf)
        if isinstance(value, GraphrtError.InvalidInput):
            buf.write_i32(3)
            _UniffiFfiConverterString.write(value.message, buf)
        if isinstance(value, GraphrtError.Plugin):
            buf.write_i32(4)
            _UniffiFfiConverterString.write(value.message, buf)
        if isinstance(value, GraphrtError.Runtime):
            buf.write_i32(5)
            _UniffiFfiConverterString.write(value.message, buf)
        if isinstance(value, GraphrtError.Unsupported):
            buf.write_i32(6)
            _UniffiFfiConverterString.write(value.message, buf)






