class _UniffiFfiConverterTypeRuntime:
    @staticmethod
    def lift(value: int) -> Runtime:
        return Runtime._uniffi_make_instance(value)

    @staticmethod
    def check_lower(value: Runtime):
        if not isinstance(value, Runtime):
            raise TypeError("Expected Runtime instance, {} found".format(type(value).__name__))

    @staticmethod
    def lower(value: Runtime) -> ctypes.c_uint64:
        return value._uniffi_clone_handle()

    @classmethod
    def read(cls, buf: _UniffiRustBuffer) -> Runtime:
        ptr = buf.read_u64()
        if ptr == 0:
            raise InternalError("Raw handle value was null")
        return cls.lift(ptr)

    @classmethod
    def write(cls, value: Runtime, buf: _UniffiRustBuffer):
        buf.write_u64(cls.lower(value))
